import React, { FunctionComponent, memo, MouseEvent, useState } from 'react';
import { useSelector } from 'react-redux'

import { preventDefault } from '@bigcommerce/checkout/dom-utils';
import { TranslatedString } from '@bigcommerce/checkout/locale';
import { ConfirmationModal } from '@bigcommerce/checkout/ui';

import { tips } from '../b3checkout/locales'

import storage from '../b3checkout/utils/storage';


export interface EditLinkProps {
    className?: string;
    isMultiShippingMode: boolean;
    url: string;
}

interface B3Store {
    global: {
        quoteId: string | number
    }
}

const EditLink: FunctionComponent<EditLinkProps> = ({ className, url, isMultiShippingMode }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);

    const gotoCartPage = () => {
        window.location.assign(url);
    };

    // if there is b3 quote checkout, user cant edit cart
    const quoteCheckoutId = storage.quoteCheckoutId.getValue()

    const {
        quoteId,
    } = useSelector(({
        global: {
            quoteId
        }
    }: B3Store) => ({
        quoteId
    }))
    const b3RoleId = storage.B3RoleId.getValue()

    const IPCheckout = storage.IPCheckout.getValue() === '1'

    if (quoteCheckoutId || quoteId || b3RoleId === '2') {
        return null
    }

    const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
        event.preventDefault();

        window.location.href = (window as any)?.B3?.setting?.store_hash ? '/account.php?action=order_status/#/invoice' : '/invoices'
      };

    if (isMultiShippingMode) {
        return (
            <>
                <ConfirmationModal
                    action={gotoCartPage}
                    headerId="cart.edit_cart_action"
                    isModalOpen={isModalOpen}
                    messageId="cart.edit_multi_shipping_cart_message"
                    onRequestClose={() => setIsModalOpen(false)}
                />
                <a
                    className={className || 'cart-header-link'}
                    data-test="cart-edit-link"
                    href="#"
                    id="cart-edit-link"
                    onClick={preventDefault(() => setIsModalOpen(true))}
                >
                    <TranslatedString id="cart.edit_cart_action" />
                </a>
            </>
        );
    }

    return (
        <>
            {
                IPCheckout ? 
                <a
                    className={className || 'cart-header-link'}
                    href="#"
                    id="cart-edit-link"
                    onClick={handleClick}
                    target="_top"
                >
                    {tips['b3.invoice.backList'] || 'Back to Invoices'}
                </a> :
                <a
                    className={className || 'cart-header-link'}
                    data-test="cart-edit-link"
                    href={url}
                    id="cart-edit-link"
                    target="_top"
                >
                    <TranslatedString id="cart.edit_cart_action" />
                </a>
            }
        </>
        
    )
};

export default memo(EditLink);
